export function translateZenGroup(group: string, language: Language): string {
  if (language === "ES") return group;
  return ZEN_GROUP_T[group]?.[language] || group;
}
export function translateZenCardName(name: string, language: Language): string {
  if (language === "ES") return name;
  return ZEN_CARD_NAME_T[name]?.[language] || name;
}
export function translateZenPhase(phase: string, language: Exclude<Language, "ES">): { phase: string; message: string; question: string; action: string } | null {
  const entry = ZEN_PHASE_T[phase];
  if (!entry) return null;
  return { phase: entry.phase[language] || phase, message: entry.message[language], question: entry.question[language], action: entry.action[language] };
}

