export function translateAngel(index: number, field: "name" | "role" | "message" | "attribute", fallback: string, language: Language): string {
  if (language === "ES") return fallback;
  const row = ANGEL_T[index];
  if (!row) return fallback;
  if (field === "name") return row.name?.[language] || fallback;
  return row[field][language] || fallback;
}
export function translateAngelKeys(index: number, fallback: string[], language: Language): string[] {
  if (language === "ES") return fallback;
  const row = ANGEL_T[index];
  if (!row) return fallback;
  return row.keys.map((k, i) => k[language] || fallback[i]);
}

// ---------- Composite card localizers (used to build the oracle deck's display fields) ----------

export function localizeZenCard(card: { name: string; group: string; phase: string; message: string; question: string; action: string }, language: Language): { name: string; theme: string; message: string; detail: string } {
  const name = translateZenCardName(card.name, language);
  if (language === "ES") return { name, theme: `${card.group} · ${card.phase}`, message: card.message, detail: `${card.question} ${card.action}` };
  const group = translateZenGroup(card.group, language);
  const p = translateZenPhase(card.phase, language as Exclude<Language, "ES">);
  return { name, theme: `${group} · ${p?.phase || card.phase}`, message: p?.message || card.message, detail: `${p?.question || card.question} ${p?.action || card.action}` };
}

export function localizeAnimalCard(card: { name: string; meaning: string; message: string }, index: number, language: Language): { name: string; theme: string; message: string; detail: string } {
  const name = translateAnimal(index, "name", card.name, language);
  const meaning = translateAnimal(index, "meaning", card.meaning, language);
  const message = translateAnimal(index, "message", card.message, language);
  const detailByLanguage: Record<Language, string> = {
    ES: `Su cualidad es ${meaning.toLowerCase()}. Observa dónde puedes aplicarla de manera concreta.`,
    EN: `Its quality is ${meaning.toLowerCase()}. Notice where you can apply it concretely.`,
    FR: `Sa qualité est ${meaning.toLowerCase()}. Observe où tu peux l'appliquer concrètement.`,
    DE: `Seine Qualität ist ${meaning.toLowerCase()}. Beobachte, wo du sie konkret anwenden kannst.`,
    PT: `Sua qualidade é ${meaning.toLowerCase()}. Observe onde você pode aplicá-la de forma concreta.`,
  };
  return { name, theme: meaning, message, detail: detailByLanguage[language] || detailByLanguage.ES };
}

const ANGEL_DETAIL_LABEL: Localized4 & { ES: string } = { ES: "Tradición de referencia", EN: "Reference tradition", FR: "Tradition de référence", DE: "Bezugstradition", PT: "Tradição de referência" };

export function localizeAngelCard(card: { name: string; role: string; family: string; message: string; attribute: string; keys: string[]; tradition: string }, index: number, language: Language): { name: string; theme: string; message: string; detail: string } {
  const name = translateAngel(index, "name", card.name, language);
  const role = translateAngel(index, "role", card.role, language);
  const family = translateAngelFamily(card.family, language);
  const message = translateAngel(index, "message", card.message, language);
  const attribute = translateAngel(index, "attribute", card.attribute, language);
  const keys = translateAngelKeys(index, card.keys, language);
  const tradition = translateAngelTradition(card.tradition, language);
  const label = ANGEL_DETAIL_LABEL[language] || ANGEL_DETAIL_LABEL.ES;
  return { name, theme: `${role} · ${family}`, message, detail: `${attribute}. ${keys.join(", ")}. ${label}: ${tradition}.` };
}
